package com.bank.coverage;

import java.util.logging.Logger;

public class CoverageRegionCounter {

    private static final Logger log = Logger.getLogger(CoverageRegionCounter.class.getName());
    private int[] parent;

    private int find(int x) {
        if (parent[x] != x) parent[x] = find(parent[x]);
        return parent[x];
    }

    private boolean union(int a, int b) {
        int ra = find(a), rb = find(b);
        if (ra == rb) return false;
        parent[ra] = rb;
        return true;
    }

    public int countRegions(char[][] grid) {
        int rows = grid.length, cols = grid[0].length;
        parent = new int[rows * cols];
        int count = 0;
        for (int r = 0; r < rows; r++)
            for (int c = 0; c < cols; c++) {
                int idx = r * cols + c;
                parent[idx] = idx;
                if (grid[r][c] == '1') count++;
            }
        for (int r = 0; r < rows; r++)
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] != '1') continue;
                int idx = r * cols + c;
                if (c + 1 < cols && grid[r][c + 1] == '1' && union(idx, idx + 1)) count--;
                if (r + 1 < rows && grid[r + 1][c] == '1' && union(idx, idx + cols)) count--;
            }
        final int result = count;
        log.info(() -> "Contiguous coverage regions: " + result);
        return count;
    }
}
