package com.bank.coverage;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

public class CoverageDemo {

    private static final Logger log = Logger.getLogger(CoverageDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — Coverage Region Counter (Union-Find)");
        char[][] grid = {
            {'1', '1', '0', '0'},
            {'1', '0', '0', '1'},
            {'0', '0', '1', '1'}
        };
        CoverageRegionCounter counter = new CoverageRegionCounter();
        int regions = counter.countRegions(grid); // expect 2
        log.info("Regions = " + regions);
    }
}
